	// HYPOTHESIS-2: Lowering the session affinity prefix threshold from 128 to 64 tokens captures more multi-turn sessions while keeping the penalty structure from Program 3
	// MECHANISM-2: Multi-turn sessions may have moderate-length prefixes that still benefit from cache locality; 64-token threshold catches these without harming load balance
	// EXPECT-2: multiturn_e2e_ms < 165
	// RESULT-2: REFUTED (actual=166.63396666666668)

	// Collect per-scorer dimension scores
	dimScoresAll := make([]map[string]float64, len(ws.scorers))
	for i, scorer := range ws.scorers {
		dimScoresAll[i] = scorer(req, snapshots)
	}

	inputLen := len(req.InputTokens)

	// Compute load statistics
	minLoad := snapshots[0].EffectiveLoad()
	maxLoad := snapshots[0].EffectiveLoad()
	sumLoad := 0
	for _, snap := range snapshots {
		load := snap.EffectiveLoad()
		if load < minLoad {
			minLoad = load
		}
		if load > maxLoad {
			maxLoad = load
		}
		sumLoad += load
	}
	avgLoad := float64(sumLoad) / float64(len(snapshots))

	// Dynamic weight adjustment based on input length
	prefixBoost := 1.0
	loadBoost := 1.0
	if inputLen < 48 {
		prefixBoost = 0.03
		loadBoost = 4.0
	} else if inputLen < 96 {
		prefixBoost = 0.15
		loadBoost = 2.8
	} else if inputLen < 192 {
		prefixBoost = 0.5
		loadBoost = 1.6
	} else {
		prefixBoost = 2.2
		loadBoost = 0.8
	}

	// SLO class adjustments
	if req.SLOClass == "realtime" {
		prefixBoost *= 0.2
		loadBoost *= 2.5
	} else if req.SLOClass == "batch" {
		prefixBoost *= 1.4
		loadBoost *= 0.7
	}

	// Session affinity boost for multi-turn
	if req.SessionID != "" && inputLen >= 64 {
		prefixBoost *= 3.0
	}

	// System stress: reduce prefix weight when average load is high
	if avgLoad > 5.0 {
		stressFactor := 1.0 / (1.0 + 0.08*(avgLoad-5.0))
		prefixBoost *= stressFactor
	}

