	scores := make(map[string]float64, len(snapshots))
	for i := range ws.scorers {
		boost := 1.0
		if i == 0 {
			boost = prefixBoost
		} else if i == 1 {
			boost = loadBoost
		}
		for _, snap := range snapshots {
			s := dimScoresAll[i][snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * ws.weights[i] * boost
