		load := snap.EffectiveLoad()
		excessLoad := load - minLoad
		if excessLoad > penaltyThreshold {
			excess := float64(excessLoad - penaltyThreshold)
			penalty := excess*penaltyPerUnit + 0.02*excess*excess
			scores[snap.ID] -= penalty
